visualization.custom_view_css:
div.ods-app-embed-dataset > div {
    height:100%;
}

.containerCarteBde{
    height:100%;
}

.filterSummaryClass{
    margin-bottom:10px;
}

.odswidget-filter-summary__active-filter-label
{
    background-color: #2C3F56;
}

.carteBde{
    display: flex;
    flex-flow: row wrap;
    height:100%;
    width:100%;
    column-gap: 10px;
}

.divListesDeroulantes{
    flex: 1 0 250px;
    margin-left:-10px;
}

.divMapClass{
    flex: 100 1 auto;
    min-width:250px;
    height:100%;
    margin-right:-10px;
}

.mapClass{
    height:100%;
    display:block;
}

.mapInfoClass h2{
    line-height:1.25rem;
}

.odswidget-select-dropdown-item-icon.fa-minus-square{color:#2C3F56;}
.odswidget-select-dropdown-item-close-icon{color:#2C3F56;}
.fa-times-circle{color:#2C3F56;}
.odswidget-select-dropdown-item-icon.fa-check-square{color:#2C3F56;}

.recherche_metier,.recherche_diplome {
    display: block;
    border-radius: 4px 4px 4px 4px;
    border-top: 1px solid #cbd2db;
    border-left: 1px solid #cbd2db;
    border-bottom: 1px solid #cbd2db;
    border-right: 1px solid #cbd2db;
    margin-top: 0px;
    margin-bottom: 0px;
    font-size: 0.8rem;
    text-decoration-color: black;
}

.recherche_metier input {
    text-indent:4px;
    height:1.8em;
}
.recherche_diplome input {
    text-indent:4px;
    height:1.8em;
}

.recherche_metier input::placeholder {
    color: #667dcf;
    opacity: 1; /* Firefox */
}
.recherche_diplome input::placeholder {
    color: #667dcf;
    opacity: 1; /* Firefox */
}

.recherche_metier input::-ms-input-placeholder { /* Edge 12 -18 */
    color: #667dcf;
}
.recherche_diplome input::-ms-input-placeholder { /* Edge 12 -18 */
    color: #667dcf;
}

.filters-tabs
{
    border:1px solid #0088cc;
    border-radius:5px;
    padding:3px;
    margin-bottom:5px; 
}

.filters-tabs .ods-simple-tabs-nav
{
    margin-bottom:5px; 
}

.filters-tabs .ods-simple-tabs-content
{
    margin-top: 0px;
    padding-top: 5px;
    margin-bottom: 10px;
    /*border-top:2px solid transparent !important;*/

}

.filters-tabs .ods-simple-tabs-nav-link
{
    color:#333333 !important;
    border-bottom:1px solid transparent !important;
    background:none !important;
    padding-top:5px;
    padding-bottom:5px;
}

.filters-tabs .ods-simple-tabs-nav-link-active:hover {
    border-bottom:1px solid #0088cc !important;
}

.filters-tabs .ods-simple-tabs-nav-link-active {
    color:hsl(200,100%,40%) !important;
    border-bottom:1px solid #0088cc !important;
    background:none !important;
}

.filters-tabs-container
{
    margin-bottom:24px;
}

/*abaisser les onglets métiers/diplomes */
.little-tabs .ods-simple-tabs-nav-item
{
    margin-bottom:0px;
    padding-bottom:0px;
}
/*abaisser les onglets métiers/diplomes */
.little-tabs .ods-simple-tabs-nav
{
    margin-bottom:0px;
    padding-bottom:0px;
}

/*contour de la liste diplomes/métiers*/
.little-tabs .ods-simple-tabs-content
{
    border:1px solid hsl(0,0%,20%) !important;
    margin-top: 0px;
    padding-bottom: 5px;
}

/*onglets métiers/diplomes*/
.little-tabs .ods-simple-tabs-nav-link
{
    border-bottom:0px;
    padding-top:5px;
    padding-bottom:5px;
    padding-left:10px;
    padding-right:10px;
    margin-bottom:-1px;
    color:hsl(0,0%,20%) !important;
    background:none !important;
}

/*onglet métiers/diplomes actif*/
.little-tabs .ods-simple-tabs-nav-link-active {
    background-color:hsl(0,0%,90%) !important;
}

/*premier onglet métier/diplome*/
.little-tabs .ods-simple-tabs-nav .ods-simple-tabs-nav-item:first-child
{
    border-top:1px solid hsl(0,0%,20%);
    border-left:1px solid hsl(0,0%,20%);
    border-right:1px solid hsl(0,0%,20%);
}

/*onglets métier/diplome suivants*/
.little-tabs .ods-simple-tabs-nav .ods-simple-tabs-nav-item:not(first-child)
{
    border-top:1px solid hsl(0,0%,20%);
    border-left:0px solid hsl(0,0%,20%);
    border-right:1px solid hsl(0,0%,20%);
}

.effacer-filtres {
    border-radius:5px;
    color: #FFF;
    background-color: #0088cc;
    text-align: center;
    padding: 10px;
}

.effacer-filtres-message
{
    margin-right:5px;
}
